package com.bank.projection;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

public class ProjectionCalculator {

    private static final Logger log = Logger.getLogger(ProjectionCalculator.class.getName());
    private final Map<Integer, Long> memo = new HashMap<>();

    // Top-down memoization of a Fibonacci-like projection recurrence
    public long projectTopDown(int n) {
        if (n <= 1) return n;
        if (memo.containsKey(n)) return memo.get(n);   // reuse overlapping subproblem
        long r = projectTopDown(n - 1) + projectTopDown(n - 2); // optimal substructure
        memo.put(n, r);
        return r;
    }

    // Bottom-up tabulation, O(1) space (keep last two states)
    public long projectBottomUp(int n) {
        if (n <= 1) return n;
        long prev2 = 0, prev1 = 1;
        for (int i = 2; i <= n; i++) {
            long cur = prev1 + prev2;                  // dp[i] = dp[i-1] + dp[i-2]
            prev2 = prev1; prev1 = cur;
        }
        log.info(() -> "Bottom-up projection for n=" + n + " computed in O(n) time, O(1) space");
        return prev1;
    }
}
