package com.bank.projection;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DpIdentifyDemo {

    private static final Logger log = Logger.getLogger(DpIdentifyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — DP Identification (memoization vs tabulation)");
        ProjectionCalculator calc = new ProjectionCalculator();
        log.info("Top-down  n=10 → " + calc.projectTopDown(10));
        log.info("Bottom-up n=10 → " + calc.projectBottomUp(10));
    }
}
